//! Review regressions for `CrlChecker` (RFC 5280 §5 / §6.3.3).
//!
//! Fixtures: `tests/fixtures/review/`, generated by `tests/gen_review_fixtures.py`
//! (stdlib Python + `openssl` CLI). Before the fix every `review_*` test
//! failed because the checker returned `Ok(())`, i.e. a false "verified not
//! revoked". `control_*` tests pin that the fixtures are sound.

use der::Decode as _;
use pkix_path::DefaultVerifier;
use pkix_revocation::{CrlChecker, Error, RevocationChecker as _};
use x509_cert::Certificate;

/// 2026-06-01T00:00:00Z — inside every review CRL's thisUpdate/nextUpdate window.
const NOW: u64 = 1_780_272_000;

fn fx(name: &str) -> Vec<u8> {
    let p = format!(
        "{}/tests/fixtures/review/{name}",
        env!("CARGO_MANIFEST_DIR")
    );
    std::fs::read(&p).unwrap_or_else(|e| panic!("{p}: {e}"))
}
fn cert(name: &str) -> Certificate {
    Certificate::from_der(&fx(name)).unwrap()
}

#[test]
fn control_base_crl_reports_serial2_revoked() {
    let r = CrlChecker::new(fx("base-crl.der"), NOW, DefaultVerifier)
        .and_then(|c| c.check_revocation(&cert("leaf-serial2.der"), &cert("ca.der")));
    assert!(matches!(r, Err(Error::Revoked { .. })), "control: {r:?}");
}

#[test]
fn control_base_plus_plain_delta_keeps_serial2_revoked() {
    let r = CrlChecker::with_delta(
        fx("base-crl.der"),
        fx("delta-crl.der"),
        NOW,
        DefaultVerifier,
    )
    .and_then(|c| c.check_revocation(&cert("leaf-serial2.der"), &cert("ca.der")));
    assert!(matches!(r, Err(Error::Revoked { .. })), "control: {r:?}");
}

/// RFC 5280 §5.2.4 / §6.3.3: a delta CRL is not a complete CRL and cannot
/// establish "not revoked" on its own. `CrlChecker::new` used to accept it
/// (only a doc comment warned), so serial 2 — revoked in the base CRL — was
/// reported not revoked. `pkix-revocation-http` feeds whatever the CDP URL returns to
/// `CrlChecker::new`, so a network attacker could swap in the CA's own delta.
#[test]
fn review_delta_crl_used_as_complete_crl_is_rejected() {
    let r = CrlChecker::new(fx("delta-crl.der"), NOW, DefaultVerifier)
        .and_then(|c| c.check_revocation(&cert("leaf-serial2.der"), &cert("ca.der")));
    assert_eq!(
        r,
        Err(Error::DeltaCrlAsComplete),
        "delta CRL (deltaCRLIndicator present) used as a complete CRL must not yield Ok(())"
    );
}

/// RFC 5280 §5.3: "If a CRL contains a critical CRL entry extension that the
/// application cannot process, then the application MUST NOT use that CRL to
/// determine the status of any certificates." (Entry-extension sibling of #9 / PKITS 4.4.10.)
#[test]
fn review_unknown_critical_crl_entry_extension_is_rejected() {
    let r = CrlChecker::new(
        fx("crl-unknown-critical-entry-ext.der"),
        NOW,
        DefaultVerifier,
    )
    .and_then(|c| c.check_revocation(&cert("leaf-serial3.der"), &cert("ca.der")));
    assert_eq!(
        r,
        Err(Error::CrlUnsupportedCriticalExtension),
        "CRL with an unrecognised critical entry extension must not be used"
    );
}

/// RFC 5280 §5.2: an unrecognised critical CRL extension forbids using the
/// CRL. Here it is on the *delta*, and the delta carries removeFromCRL for
/// serial 2, so using it un-revokes a key-compromised certificate.
/// (Delta-CRL sibling of #9 / PKITS 4.4.10; worse because it overrides a revocation.)
#[test]
fn review_delta_with_unknown_critical_extension_is_not_applied() {
    let r = CrlChecker::with_delta(
        fx("base-crl.der"),
        fx("delta-crl-unknown-critical-ext.der"),
        NOW,
        DefaultVerifier,
    )
    .and_then(|c| c.check_revocation(&cert("leaf-serial2.der"), &cert("ca.der")));
    assert_eq!(
        r,
        Err(Error::CrlUnsupportedCriticalExtension),
        "delta with unknown critical extension must not un-revoke serial 2"
    );
}

/// RFC 5280 §6.3.3(c)(2)/(3): the delta CRL must have the same
/// issuingDistributionPoint as the complete CRL (here: base has none, delta
/// is scoped to another partition). The delta's removeFromCRL is applied anyway.
#[test]
fn review_delta_with_different_idp_scope_is_not_applied() {
    let r = CrlChecker::with_delta(
        fx("base-crl.der"),
        fx("delta-crl-scope-mismatch.der"),
        NOW,
        DefaultVerifier,
    )
    .and_then(|c| c.check_revocation(&cert("leaf-serial2.der"), &cert("ca.der")));
    assert_eq!(
        r,
        Err(Error::DeltaCrlBaseMismatch),
        "delta with a different IDP scope than its base must not un-revoke serial 2"
    );
}
